"const sql = require('mssql');

const dbConfig = {
  server: 'localhost',
  database: 'ControlabIA',
  user: 'controlab_user',
  password: 'Delicia1.',
  port: 1433,
  options: {
    encrypt: false,
    trustServerCertificate: true,
    enableArithAbort: true
  }
};

async function checkStock() {
  try {
    const pool = await sql.connect(dbConfig);
    console.log('Connected to database.');

    const countResult = await pool.request().query('SELECT COUNT(*) as cnt FROM items_inventario');
    console.log('Total items in items_inventario:', countResult.recordset[0].cnt);

    const activeCount = await pool.request().query('SELECT COUNT(*) as cnt FROM items_inventario WHERE activo = 1');
    console.log('Active items (activo = 1):', activeCount.recordset[0].cnt);

    const categoriesResult = await pool.request().query(`
      SELECT categoria, COUNT(*) as count, SUM(stock_actual) as sum_stock, SUM(precio_costo) as sum_cost
      FROM items_inventario
      GROUP BY categoria
    `);
    console.log('Categories overview:');
    console.table(categoriesResult.recordset);

    const sampleItems = await pool.request().query('SELECT TOP 10 id, codigo, nombre, categoria, stock_actual, activo FROM items_inventario');
    console.log('Sample items:');
    console.table(sampleItems.recordset);

    await pool.close();
  } catch (e) {
    console.error('Error:', e);
  }
}

checkStock();
"

